    21  ushort LibRaw::sget2Rev(uchar *s) // specific to some Canon Makernotes fields,
    22                                    // where they have endian in reverse
    23  {
    24    if (order == 0x4d4d) /* "II" means little-endian, and we reverse to "MM" - big
    25                            endian */
    26      return s[0] | s[1] << 8;
    27    else /* "MM" means big-endian... */
    28      return s[0] << 8 | s[1];
    29  }
