    31  ushort libraw_sget2_static(short _order, uchar *s)
    32  {
    33      if (_order == 0x4949) /* "II" means little-endian */
    34          return s[0] | s[1] << 8;
    35      else /* "MM" means big-endian */
    36          return s[0] << 8 | s[1];
    37  }
